// Hardware probe: EE ADD.S guard bits / sticky (evidence register 1.2)
// Generated by tools/semantics/make_probes.py. Build with ps2sdk inside ps2autotests (tests/cpu/...); NOT built or
// run by Zmbor. Prints one line per operand pair: "<fs> <ft> <result>" in hex.
#include <common-ee.h>

static const u32 kPairs[][2] = {
	{0x348EA4D0, 0xB3696EC5},
	{0x3E85360C, 0xB8B41003},
	{0x456D7AFB, 0xC42A53A1},
	{0x4157B5B9, 0xBF0F86D1},
	{0x33E987E4, 0x9941A231}
};

int main(int argc, char *argv[]) {
	printf("-- TEST BEGIN\n");
	for (u32 i = 0; i < sizeof(kPairs) / sizeof(kPairs[0]); ++i) {
		u32 r;
		asm volatile (
			"mtc1 %1, $f1\n"
			"mtc1 %2, $f2\n"
			"add.s $f0, $f1, $f2\n"
			"mfc1 %0, $f0\n"
			: "=r"(r) : "r"(kPairs[i][0]), "r"(kPairs[i][1]) : "memory");
		printf("%08x %08x %08x\n", kPairs[i][0], kPairs[i][1], r);
	}
	printf("-- TEST END\n");
	return 0;
}
